INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d1d2d3d4-4404-4000-8000-000000000004', 'b1b2c3d4-4444-4000-8000-000000000004', 4, 'Reflexão: Meu Corpo como Linguagem', 'Integrar corpo e espírito', '{"text": "S\u00e3o Jo\u00e3o Paulo II nos convida a uma revolu\u00e7\u00e3o interior: ver o corpo como linguagem do amor.\n\nReflita:\n1. **Como eu trato meu corpo?** Com respeito ou neglig\u00eancia?\n2. **Como eu olho para o corpo dos outros?** Com rever\u00eancia ou objetifica\u00e7\u00e3o?\n3. **Minha cultura me ajuda ou atrapalha** a viver a verdade do corpo?\n4. **Em que \u00e1reas da minha vida** preciso de purifica\u00e7\u00e3o do olhar?\n5. **Como posso viver a castidade** como afirma\u00e7\u00e3o do amor, n\u00e3o como repress\u00e3o?\n\nA castidade n\u00e3o \u00e9 dizer \"n\u00e3o\" ao corpo \u2014 \u00e9 dizer \"sim\" ao amor verdadeiro.", "prompt": "Escreva sobre como a cultura atual influencia sua vis\u00e3o do corpo e da sexualidade. Como a Teologia do Corpo pode transformar esse olhar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;